Now let me write the Stimulus notifications controller. Design based on the design-shipped partials and CSS:

- The element with `data-controller="notifications"` gets class `notifications--on` (via `on` class value) when this device has an active push subscription and permission granted.
- `details` targets (the help blocks) are shown when permission is denied, hidden otherwise.
- Buttons: turn on / turn off.

```js
import { Controller } from "@hotwired/stimulus"
import { post, destroy } from "@rails/request.js"

export default class extends Controller {
  static classes = [ "on" ]
  static targets = [ "details" ]
  static values = { url: String, vapidPublicKey: String }

  async connect() {
    if (this.#supported) {
      this.element.classList.toggle(this.onClass, await this.#subscribed())
      this.#toggleDetails(this.#permission == "denied")
    }
  }

  async turnOn() {
    if (this.#supported) {
      const permission = await Notification.requestPermission()

      if (permission == "granted") {
        await this.#subscribe()
        this.element.classList.add(this.onClass)
      }

      this.#toggleDetails(permission == "denied")
    }
  }

  async turnOff() {
    const subscription = await this.#pushSubscription()

    if (subscription) {
      await subscription.unsubscribe()
      await destroy(this.urlValue, { body: { endpoint: subscription.endpoint } })
    }

    this.element.classList.remove(this.onClass)
  }

  // Private

  get #supported() {
    return "Notification" in window && "serviceWorker" in navigator && "PushManager" in window
  }

  get #permission() {
    return Notification.permission
  }

  async #subscribed() {
    return this.#permission == "granted" && await this.#pushSubscription() != null
  }

  async #subscribe() {
    const subscription = await this.#pushRegistration().then(registration =>
      registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: this.#decodedVapidPublicKey })
    )

    const { endpoint, keys } = subscription.toJSON()

    await post(this.urlValue, { body: { push_subscription: { endpoint: endpoint, p256dh_key: keys.p256dh, auth_key: keys.auth } } })
  }
  ...
}
```

