import { Controller } from "@hotwired/stimulus"
import { destroy, post } from "@rails/request.js"

export default class extends Controller {
  static classes = [ "on" ]
  static targets = [ "details" ]
  static values = { url: String, vapidPublicKey: String }

  async connect() {
    if (this.#supported) {
      this.element.classList.toggle(this.onClass, await this.#subscribed())
      this.#toggleDetails(this.#permission === "denied")
    }
  }

  async turnOn() {
    if (this.#supported) {
      const permission = await Notification.requestPermission()

      if (permission === "granted" && await this.#subscribe()) {
        this.element.classList.add(this.onClass)
      }

      this.#toggleDetails(permission === "denied")
    }
  }

  async turnOff() {
    const subscription = await this.#pushSubscription()

    if (subscription) {
      await subscription.unsubscribe()
